alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = (select auth.uid())
      and tm.role = 'editor'
  );
$$;

create or replace function public.document_team_id(p_document_id bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select d.team_id from public.documents d where d.id = p_document_id;
$$;

create or replace function public.enforce_document_insert()
returns trigger
language plpgsql
as $$
begin
  if (select auth.role()) = 'anon' then
    raise exception 'documents are not accessible to anonymous users';
  end if;
  if new.deleted_at is not null then
    raise exception 'documents cannot be inserted with deleted_at set';
  end if;
  if not exists (
    select 1
    from public.team_members tm
    where tm.team_id = new.team_id
      and tm.user_id = (select auth.uid())
      and tm.role = 'editor'
  ) then
    raise exception 'only team editors can create documents';
  end if;
  if new.created_by <> (select auth.uid()) then
    raise exception 'documents must be created by the current user';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_document_update()
returns trigger
language plpgsql
as $$
begin
  if old.team_id <> new.team_id then
    raise exception 'document team cannot be changed';
  end if;
  if new.deleted_at is not distinct from old.deleted_at then
    if not exists (
      select 1
      from public.team_members tm
      where tm.team_id = new.team_id
        and tm.user_id = (select auth.uid())
        and tm.role = 'editor'
    ) then
      raise exception 'only team editors can edit documents';
    end if;
  else
    raise exception 'deleted status of a document cannot be changed';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_document_delete()
returns trigger
language plpgsql
as $$
begin
  if (select auth.role()) = 'anon' then
    raise exception 'documents are not accessible to anonymous users';
  end if;
  if auth.uid() <> (select created_by from public.documents where id = old.id) then
    raise exception 'only the document creator can delete it';
  end if;
  return old;
end;
$$;

create trigger enforce_documents_insert
before insert on public.documents
for each row execute function public.enforce_document_insert();

create trigger enforce_documents_update
before update on public.documents
for each row execute function public.enforce_document_update();

create trigger enforce_documents_delete
before delete on public.documents
for each row execute function public.enforce_document_delete();

create policy teams_select_member
on public.teams for select to authenticated
using (public.is_team_member(id));

create policy team_members_select_own
on public.team_members for select to authenticated
using (user_id = (select auth.uid()));

create policy documents_select_team_member
on public.documents for select to authenticated
using (public.is_team_member(team_id) and deleted_at is null);

create policy documents_insert_team_editor
on public.documents for insert to authenticated
with check (public.is_team_editor(team_id));

create policy documents_update_team_editor
on public.documents for update to authenticated
using (public.is_team_editor(team_id))
with check (public.is_team_editor(team_id));

create policy documents_delete_creator
on public.documents for delete to authenticated
using (created_by = (select auth.uid()));
