    raise exception 'only the document creator can delete a document';
  end if;
  if new.deleted_at is not distinct from old.deleted_at then
    if not public.is_team_editor(public.document_team_id(old.id)) then
      raise exception 'only team editors can edit documents in this team';
    end if;
    if new.team_id is distinct from old.team_id then
      raise exception 'document team_id cannot be changed';
    end if;
    return new;
  end if;
  raise exception 'documents may only be updated to mark them as deleted';
end;
$$;

