create or replace function public.enforce_invoice_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'new invoices must be created with status draft';
    end if;
    if new.created_by <> (select auth.uid()) then
      raise exception 'invoice created_by must be the current user';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if (select auth.uid()) is distinct from public.invoice_created_by(old.id)
       and not public.is_finance_staff() then
      raise exception 'invoice may not be modified';
    end if;

    if old.status <> 'draft' then
      if (select auth.uid()) is distinct from public.invoice_created_by(old.id) then
        if old.status <> 'sent' then
          raise exception 'invoice status may not be changed';
        end if;
        if new.status not in ('paid', 'void') then
          raise exception 'sent invoice status must become paid or void';
        end if;
        if new.customer is distinct from old.customer
           or new.amount is distinct from old.amount then
          raise exception 'customer and amount of a non-draft invoice may not be changed';
        end if;
      else
        if old.status <> 'draft' then
          raise exception 'invoice status may not be changed';
        end if;
        if new.status not in ('draft', 'sent') then
          raise exception 'draft invoice status must remain draft or become sent';
        end if;
        if new.customer is distinct from old.customer
           or new.amount is distinct from old.amount then
          raise exception 'draft invoice customer and amount may be changed';
        end if;
      end if;
    else
      if (select auth.uid()) is distinct from public.invoice_created_by(old.id) then
        if old.status <> 'sent' then
          raise exception 'invoice status may not be changed';
        end if;
        if new.status not in ('paid', 'void') then
          raise exception 'sent invoice status must become paid or void';
        end if;
        if new.customer is distinct from old.customer
           or new.amount is distinct from old.amount then
          raise exception 'customer and amount of a non-draft invoice may not be changed';
        end if;
      else
        if new.status not in ('draft', 'sent') then
          raise exception 'draft invoice status must remain draft or become sent';
        end if;
        if new.customer is distinct from old.customer
           or new.amount is distinct from old.amount then
          raise exception 'draft invoice customer and amount may be changed';
        end if;
      end if;
    end if;
    return new;
  end if;

  return new;
end;
$$;

