create or replace function public.is_restaurant_staff(p_restaurant_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.restaurant_staff
    where restaurant_id = p_restaurant_id
      and user_id = (select auth.uid())
  );
$$;

create or replace function public.reservation_booked(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.reservations
    where id = p_reservation_id
      and status = 'booked'
  );
$$;

create or replace function public.reservation_in_future(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.reservations
    where id = p_reservation_id
      and reserved_for > now()
  );
$$;

create or replace function public.reservation_time_passed(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.reservations
    where id = p_reservation_id
      and reserved_for <= now()
  );
$$;

create or replace function public.enforce_reservation_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id <> (select auth.uid()) then
      raise exception 'reservations.user_id must match the authenticated user';
    end if;
    if new.reserved_for <= now() then
      raise exception 'reservations.reserved_for must be in the future';
    end if;
    if new.status <> 'booked' then
      raise exception 'new reservations must have status booked';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.id <> new.id
       or old.restaurant_id <> new.restaurant_id
       or old.user_id <> new.user_id then
      raise exception 'reservations id, restaurant_id, and user_id cannot be changed';
    end if;

    if (select auth.uid()) is null then
      raise exception 'reservations update requires authentication';
    end if;

    if public.reservation_booked(old.id) then
      if (select auth.uid()) = old.user_id then
        if old.reserved_for > now() then
          if new.status = 'cancelled' then
            return new;
          else
            raise exception 'booked reservations can only be cancelled';
          end if;
        else
          raise exception 'booked reservations in the past cannot be modified';
        end if;
      elsif public.is_restaurant_staff(old.restaurant_id) then
        if old.reserved_for <= now() then
          if new.status in ('seated', 'no_show') then
            return new;
          else
            raise exception 'booked reservations can only be marked seated or no_show';
          end if;
        else
          raise exception 'booked reservations in the future cannot be modified by staff';
        end if;
      else
        raise exception 'invalid reservation update';
      end if;
    else
      raise exception 'reservation is not booked';
    end if;
  end if;

  raise exception 'invalid trigger operation';
end;
$$;

create trigger enforce_reservation_update_trigger
before insert or update on public.reservations
for each row execute function public.enforce_reservation_update();

