language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if (select auth.jwt() ->> 'app_metadata.role') = 'auditor' then
    raise exception 'auditors cannot modify stock';
  end if;

  if public.location_frozen(new.location_id) then
    raise exception 'stock cannot be modified while location is frozen';
  end if;

  if not public.is_staff_at(new.location_id) then
    raise exception 'only staff can modify stock at this location';
  end if;

  return new;
end;
$$;

