create or replace function publicissue_guard()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new issues must be open';
    end if;
    if new.is_confidential is distinct from false then
      if not exists (
        select 1
        from public.project_members pm
        where pm.project_id = new.project_id
          and pm.user_id = public.current_user_id()
          and pm.role = 'maintainer'
      ) then
        raise exception 'only maintainers can create confidential issues';
      end if;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if public.current_user_id() is distinct from (select reporter_id from public.issues where id = old.id) then
      if not public.can_see_issue(old.id) then
        raise exception 'issue is not visible';
      end if;
    end if;

    if public.is_project_maintainer(old.project_id) then
      return new;
    end if;

    if new.id <> old.id
       or new.project_id <> old.project_id
       or new.title <> old.title
       or new.reporter_id <> old.reporter_id then
      raise exception 'immutable issue fields';
    end if;

    if new.is_confidential is distinct from old.is_confidential then
      raise exception 'only maintainers can change confidentiality';
    end if;

    if old.status = 'closed' then
      raise exception 'closed issues cannot be updated';
    end if;

    return new;
  end if;

  raise exception 'unknown trigger operation';
end;
$$;

