alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

create policy "pharmacists_select_authenticated"
on public.pharmacists for select to authenticated
using (true);

create policy "prescriptions_select_patient_pharmacist"
on public.prescriptions for select to authenticated
using (patient_id = (select auth.uid())
     or exists (select 1 from public.pharmacists p where p.user_id = (select auth.uid())))
     or exists (select 1 from public.dispenses d where d.prescription_id = prescriptions.id and d.pharmacist_id = (select auth.uid())));

create policy "dispenses_select_patient_pharmacist"
on public.dispenses for select to authenticated
using (pharmacist_id = (select auth.uid())
     or exists (select 1 from public.prescriptions p where p.id = dispenses.prescription_id and p.patient_id = (select auth.uid())));

create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_pharmacist_id uuid := auth.uid();
  v_prescription public.prescriptions%rowtype;
  v_refills_left integer;
begin
  if v_pharmacist_id is null then
    raise exception 'not authenticated';
  end if;

  select * into v_prescription
  from public.prescriptions
  where id = p_prescription_id
  for update;

  if not found then
    raise exception 'prescription not found';
  end if;

  if v_prescription.patient_id = v_pharmacist_id then
    raise exception 'cannot dispense own prescription';
  end if;

  if not exists (
    select 1
    from public.pharmacists
    where user_id = v_pharmacist_id
  ) then
    raise exception 'caller is not a pharmacist';
  end if;

  if v_prescription.expires_at < now() then
    raise exception 'prescription has expired';
  end if;

  if v_prescription.refills_left <= 0 then
    raise exception 'no refills left';
  end if;

  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  v_refills_left := (select refills_left from public.prescriptions where id = p_prescription_id);

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  return v_refills_left;
end;
$$;

revoke all on table public.pharmacists from public, anon, authenticated;
revoke all on table public.prescriptions from public, anon, authenticated;
revoke all on table public.dispenses from public, anon, authenticated;
revoke all on sequence public.dispenses_id_seq from public, anon, authenticated;

grant select on table public.pharmacists to authenticated;
grant select on table public.prescriptions to authenticated;
grant select on table public.dispenses to authenticated;

revoke execute on function public.dispense(bigint) from public, anon;
grant execute on function public.dispense(bigint) to authenticated;
```

