alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

create policy "envelopes_select_sender_or_recipient"
on public.envelopes for select to authenticated
using (sender_id = (select auth.uid())
     or exists (select 1 from public.envelope_recipients r where r.envelope_id = envelopes.id and r.user_id = (select auth.uid())));

create policy "envelope_recipients_select_sender_or_recipient"
on public.envelope_recipients for select to authenticated
using (exists (select 1 from public.envelopes e where e.id = envelope_recipients.envelope_id and (e.sender_id = (select auth.uid()) or envelope_recipients.user_id = (select auth.uid()))));

create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
  v_signed_count integer;
  v_total_count integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if not exists (
    select 1
    from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = v_uid
  ) then
    raise exception 'not a recipient';
  end if;

  if exists (
    select 1
    from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = v_uid and signed_at is not null
  ) then
    raise exception 'already signed';
  end if;

  select count(*) into v_total_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_uid;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed_count < v_total_count then
    if exists (
      select 1
      from public.envelope_recipients r
      where r.envelope_id = p_envelope_id
      and r.sign_order < (select r2.sign_order from public.envelope_recipients r2 where r2.envelope_id = p_envelope_id and r2.user_id = v_uid)
      and r.signed_at is null
    ) then
      raise exception 'a previous signer has not signed yet';
    end if;
  else
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_envelope public.envelopes%rowtype;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_envelope
  from public.envelopes
  where id = p_envelope_id
  for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope.sender_id <> v_uid then
    raise exception 'only the sender can void an envelope';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;
