create or replace function public.proposal_undecided(p_proposal_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select p.status = 'submitted' or p.status = 'accepted' from public.proposals p where p.id = p_proposal_id),
