    where p.id = p_proposal_id
      and p.status in ('rejected', 'accepted')
  );
$$;

create or replace function public.prevent_reviewer_self_review()
returns trigger
language plpgsql
as $$
begin
  if new.reviewer_id = new.proposal_id::uuid then
    raise exception 'reviewers cannot review their own proposals';
  end if;
  return new;
end;
$$;

