create or replace function public.is_resident(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_hoa_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.hoa_admins h
    where h.user_id = (select auth.uid())
  );
$$;

create or replace function public.active_permit_count(p_unit_id bigint)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer
  from public.permits p
  where p.unit_id = p_unit_id
    and not p.revoked
    and p.valid_until >= current_date;
$$;

create or replace function public.enforce_permit_insert()
returns trigger
language plpgsql
as $$
begin
  if (select auth.role()) = 'service_role' then
    return new;
  end if;

  if not exists (
    select 1
    from public.residents r
    where r.unit_id = new.unit_id
      and r.user_id = (select auth.uid())
  ) then
    raise exception 'only residents can add permits for their unit';
  end if;

  if public.active_permit_count(new.unit_id) >= 2 then
    raise exception 'unit already has 2 or more active permits';
  end if;

  if new.revoked then
    raise exception 'new permits cannot be revoked';
  end if;

  if new.valid_until < current_date then
    raise exception 'permit must be valid for at least today';
  end if;

  if new.valid_until > current_date + interval '365 days' then
    raise exception 'permit validity cannot exceed 365 days from today';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_permit_update()
returns trigger
language plpgsql
as $$
begin
  if (select auth.role()) = 'service_role' then
    return new;
  end if;

  if old.revoked and new.revoked = false then
    raise exception 'permits cannot be un-revoked';
  end if;

  if public.is_hoa_admin() then
    if new.revoked then
      return new;
    else
      raise exception 'hoa admins can only revoke permits';
    end if;
  end if;

  if not public.is_resident(old.unit_id) then
    raise exception 'only residents of this unit can update permits';
  end if;

  if new.unit_id <> old.unit_id then
    raise exception 'permit unit cannot be changed';
  end if;

  if new.valid_until <> old.valid_until then
    raise exception 'permit validity cannot be changed';
  end if;

  if new.revoked <> old.revoked then
    raise exception 'permit revocation status cannot be changed by residents';
  end if;

  return new;
end;
$$;

create trigger enforce_permit_insert_trigger
before insert on public.permits
for each row execute function public.enforce_permit_insert();

create trigger enforce_permit_update_trigger
before update on public.permits
for each row execute function public.enforce_permit_update();

create policy residents_select_own_residence
on public.residents for select to authenticated
using (user_id = (select auth.uid()));

create policy permits_select_resident_unit
on public.permits for select to authenticated
using (public.is_resident(unit_id));

create policy permits_select_hoa_admin
on public.permits for select to authenticated
using (public.is_hoa_admin());

create policy permits_insert_resident_unit
on public.permits for insert to authenticated
with check (public.is_resident(unit_id));

create policy permits_update_resident_plate
on public.permits for update to authenticated
using (public.is_resident(unit_id))
with check (public.is_resident(unit_id));

revoke all on table public.residents from public, anon, authenticated;
revoke all on table public.hoa_admins from public, anon, authenticated;
