    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = (select auth.uid())
  );
$$;

create or replace function public.hoa_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.hoa_admins h
    where h.user_id = (select auth.uid())
  );
$$;

create or replace function public.active_permit_count(p_unit_id bigint)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer
  from public.permits p
  where p.unit_id = p_unit_id
    and not p.revoked
    and p.valid_until >= current_date;
$$;

create or replace function public.enforce_perit_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.revoked then
      raise exception 'new permits cannot be revoked';
    end if;
    if (select date_diff('day', current_date, new.valid_until)) > 365 then
      raise exception 'permit validity cannot exceed 365 days';
    end if;
    if not public.is_resident(new.unit_id) then
      raise exception 'only residents can add permits for their unit';
    end if;
    if public.active_permit_count(new.unit_id) >= 2 then
      raise exception 'unit already has 2 active permits';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if old.revoked and not new.revoked then
      raise exception 'a revoked permit cannot be un-revoked';
    end if;
    if public.hoa_admin() then
      if new.revoked = false and old.revoked = true then
        raise exception 'revoked permits cannot be un-revoked';
      end if;
      return new;
    end if;
    if not public.is_resident(old.unit_id) then
      raise exception 'only residents or HOA admins can update permits';
    end if;
    if new.unit_id <> old.unit_id then
      raise exception 'permit unit cannot be changed';
    end if;
    if new.valid_until <> old.valid_until then
      raise exception 'permit validity cannot be changed by residents';
    end if;
    if not new.revoked and old.revoked then
      raise exception 'revoked permits cannot be un-revoked';
    end if;
    return new;
  end if;

  return new;
end;
$$;

