on public.permits for update to authenticated
using (public.hoa_admin())
with check (public.hoa_admin());

revoke all on table public.residents from public, anon, authenticated;
revoke all on table public.hoa_admins from public, anon, authenticated;
revoke all on table public.permits from public, anon, authenticated;
revoke all on sequence public.permits_id_seq from public, anon, authenticated;

